function parseJson(raw, label) {
  let text = typeof raw === 'string' ? raw.trim() : JSON.stringify(raw);
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  try {
    return JSON.parse(text);
  } catch (err) {
    const objStart = text.indexOf('{');
    const objEnd = text.lastIndexOf('}');
    if (objStart >= 0 && objEnd > objStart) return JSON.parse(text.slice(objStart, objEnd + 1));
    const arrStart = text.indexOf('[');
    const arrEnd = text.lastIndexOf(']');
    if (arrStart >= 0 && arrEnd > arrStart) return JSON.parse(text.slice(arrStart, arrEnd + 1));
    throw new Error(`${label} was not valid JSON: ${err.message}`);
  }
}

function parseMoney(value) {
  if (value == null) return null;
  const cleaned = String(value).replace(/[^0-9.]/g, '');
  return cleaned ? Number(cleaned) : null;
}

function normalise(value) {
  return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function buildRateMap(rateCardText) {
  const text = typeof rateCardText === 'string' ? rateCardText : JSON.stringify(rateCardText);
  const start = text.indexOf('Role,Discipline,Seniority band');
  if (start < 0) throw new Error('Could not find Rate Card table header.');

  const endMarkers = ['Notes & assumptions', '--- Sheet: Cost Modeller ---'];
  let end = text.length;
  for (const marker of endMarkers) {
    const idx = text.indexOf(marker, start);
    if (idx > start && idx < end) end = idx;
  }

  const block = text.slice(start, end).trim();
  const parsed = CSV.parse(block, { header: true, skipEmptyLines: true });
  if (parsed.errors && parsed.errors.length) {
    // Continue where possible; PapaParse may warn about trailing blank lines.
  }

  const rows = parsed.data || [];
  const rates = new Map();
  for (const row of rows) {
    const keys = Object.keys(row);
    const roleKey = keys.find(k => normalise(k) === 'role');
    const seniorityKey = keys.find(k => normalise(k).includes('seniority band'));
    const midKey = keys.find(k => normalise(k).includes('day rate') && normalise(k).includes('mid'));
    if (!roleKey || !seniorityKey || !midKey) continue;

    const role = row[roleKey];
    const seniority = row[seniorityKey];
    const rate = parseMoney(row[midKey]);
    if (role && seniority && rate) {
      rates.set(`${normalise(role)}|${normalise(seniority)}`, { role, seniority, midDayRate: rate });
    }
  }
  return rates;
}

