function money(value) {
  if (value == null || Number.isNaN(Number(value))) return 'TBC';
  return '£' + Math.round(Number(value)).toLocaleString('en-GB');
}

function textList(items) {
  if (!items || !items.length) return '- TBC / for human review\n';
  return items.map(item => `- ${String(item).replace(/\n/g, ' ')}`).join('\n') + '\n';
}

function cell(value) {
